class Order {
    private Customer c = new Customer();
    private OrderLine ol = new OrderLine();

    public double calculatePrice() {
        int qty = ol.getQuantity();
        Product p = ol.getProduct();
        double price = p.getPricingDetails();
        double bPrice = calculateBasicPrice(qty, price);
        double discount = calculateDiscounts();
        return calculateTotalPrice(price, discount);
    }

    private double calculateBasicPrice(int qty, double price) { return qty * price; }
    private double calculateDiscounts() { return c.getDiscountInfo(); }
    private double calculateTotalPrice(double price, double discount) { return price * discount; }
}

import java.util.ArrayList;
import java.util.List;

class Item {
    boolean isTaxable() { return true; }
    double getPrice() { return 1.0; }
}

class TaxCalc {
    double tax(double p) { return p * 0.09; }
}

class Cart {
    private List<Item> items = new ArrayList<>();
    private TaxCalc calc = new TaxCalc();

    double total() {
        double sum = 0;
        for (Item it : items) {
            double p = it.getPrice();
            if (it.isTaxable()) {
                p = p + calc.tax(p);
            }
            sum = sum + p;
        }
        return sum;
    }
}
